  {"prompt": "Συνώνυμο/ορισμός: το πιο χαμηλό σημείο, το βάθος", "options": [], "answer": "πάτο", "answer_note": "ο πάτος = bottom."},
  {"prompt": "Συνώνυμο/ορισμός: ρέει, προχωρά αργά", "options": [], "answer": "κυλά", "answer_note": "κυλώ/κυλάω = to roll, flow."},
  {"prompt": "Συνώνυμο/ορισμός: απότομα, κάθετα βράχια", "options": [], "answer": "γκρεμούς", "answer_note": "ο γκρεμός = cliff, precipice."},
  {"prompt": "Συνώνυμο/ορισμός: πλήρης, χωρίς καμία εξαίρεση", "options": [], "answer": "απόλυτη", "answer_note": "απόλυτος = absolute, complete."},
